from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """##### 出目42 <トリップワイヤー>\n\n- 属性：屋外\n_あっ！驚嘆の声を上げたのは..._\n被弾ロールを振る。対処の分隊員は防御ロール(目標値：3)を行う。\n- 成功：転倒するが爆発は免れる。何も起こらない。\n- 失敗：小爆発が起きる。対象の隊員は次の戦闘の最初のラウンドにおいて、攻撃ロールを行うことができない。\n- 失敗(ファンブル)：爆発が直撃する。対象の隊員は1ダメージを受ける。\n"""
new = """##### 出目42 <トリップワイヤー>\n\n- 属性：屋外\n_あっ！驚嘆の声を上げたのは..._\n【被弾ロール】を振る。対象の分隊員は防御ロール(目標値：3)を行う。被弾ロールの対象となれる戦闘員が1名もいない場合は、分隊長を対象として同じ防御ロールを行う。\n- 成功：転倒するが爆発は免れる。何も起こらない。\n- 失敗：小爆発が起きる。対象が分隊員の場合、その隊員は次の戦闘の最初のラウンドにおいて攻撃ロールを行うことができない。対象が分隊長の場合、分隊長は次の戦闘の第1ラウンドに攻撃ロールを行うことができない。\n- 失敗(ファンブル)：爆発が直撃する。対象は1ダメージを受ける。\n"""
if s.count(old) != 1:
    raise SystemExit(f"event42 marker count must be 1, got {s.count(old)}")
scenario.write_text(s.replace(old, new, 1), encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 27. Black Sun 出目42の被弾対象フォールバック — 採用済み"
section = """

## 27. Black Sun 出目42の被弾対象フォールバック — 採用済み

ユーザー承認により、出目42【トリップワイヤー】で【被弾ロール】の対象となれる戦闘員が1名もいない場合の処理を明確化する。

- 通常は【被弾ロール】で対象となる分隊員を決定し、その分隊員が目標値3の防御ロールを行う。
- 被弾ロールの対象となれる戦闘員が1名もいない場合は、分隊長を対象として同じ防御ロールを行う。
- 防御成功なら何も起こらない。
- 通常失敗の場合、対象が分隊員ならその隊員、分隊長なら分隊長が、次の戦闘の第1ラウンドに攻撃ロールを行えない。
- ファンブルの場合、対象が分隊員／分隊長のどちらであっても1ダメージを受ける。
- 既存本文の誤記「対処の分隊員」は「対象の分隊員」に修正する。

これにより、戦闘員不在の編成や全戦闘員脱落後でもイベント処理が停止せず、既存の効果強度を維持したまま分隊長へフォールバックできる。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
